    {
      "path": "/components/CTAFooter.jsx",
      "content": "import Icon from '@global/Icon';

export const displayName = 'CTA Footer Section';
export const shortDescription = 'Full-width CTA banner and site footer';

const footerLinks = {
  [t('Product')]: [t('Features'), t('Pricing'), t('Changelog'), t('Roadmap')],
